head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.spanYN = "N"; // 기업인수목적 회사 구분
scwin.strCbd_MF = "(null)^선택해주세요,0^매매거래정지 지정,2^매매거래정지 및 정지해제";
scwin.bndYN = "N";
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
scwin.pMenuID = $c.stf.InfoMenuID();
scwin.fr_SecuGrpId = $c.lc.fn_getSecuGrpId($c.stf.InfoMenuID()); // mid 부모프레임으로 부터 받은 menu id로 증권그룹id를 반환하는 함수 호출, 법인선택팝업에서 fr_SecuGrpId 변수를 참조.
scwin.fr_MktId = $c.lc.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(panel_Top);
        if (scwin.fr_SecuGrpId === 'MF') {
            // by nhkw 20181116
            cmb_RegistTyp.CBData = scwin.strCbd_MF;
        }
        await scwin.directDlsclsStatus();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Excel_onclick = async function() {
    try {
        if (dts_List.getRowCount() > 0) {
            // 엑셀 로그
            $c.stf.doLogSave("ULDSTF05206.xml", SCREN_PROCS_TP_CD_07);
            $c.data.downloadGridViewExcel(grd_List, {fileName: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "매매거래정지내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.img_Excel_onclick" });
    }
};

/**
 * @method
 * @name img_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Search_onclick = async function() {
    try {
        if (txb_IsurCd.getValue() !== "") {
            await scwin.search();
        } else {
            await $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.img_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_IsuCdSearch_onclick
 * @description btn_IsuCdSearch 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_IsuCdSearch_onclick = function() {
    try {
        scwin.fn_GetPar = scwin.getParIsur;
        scwin.fn_SetPar = scwin.setParIsur;

        // 기업인수목적 회사와 주권 목록을 나눔 2010.05.30
        if (scwin.pMenuID === "STF05206") {
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "2");
        } else if (scwin.pMenuID === "STF05261") {
            // 기업인수목적 회사
            $c.lc.fn_PopFindCorpChrgSW(scwin.fr_SecuGrpId, "1");
            scwin.spanYN = "Y";
        } else {
            $c.lc.fn_PopFindCorpChrg(scwin.fr_SecuGrpId);
        }

        // fn_PopFindCorpChrg(fr_SecuGrpId);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05206.btn_IsuCdSearch_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {void}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    try {
        $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05206.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name img_Close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.img_Close_onclick = function() {
    try {
        window.close();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05206.img_Close_onclick" });
    }
};

/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (txb_IsurCd.getValue() === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0013", ""));
            txb_IsurCd.focus();
            return true;
        }
        if (cmb_RegistTyp.getSelectedIndex() === 0) {
            await $c.win.alert($c.stf.getMessageParam("MSG-0014", ""));
            cmb_RegistTyp.focus();
            return true;
        }
        scwin.bndYN = await scwin.bndListCorpYn();
        if (scwin.bndYN === 'Y' &&
            (cmb_RegistTyp.BindColVal === "0" || cmb_RegistTyp.BindColVal === "2" || cmb_RegistTyp.BindColVal === "6") &&
            scwin.fr_SecuGrpId === 'ST') {
            await $c.win.alert($c.stf.getMessageParam("MSG-0027", dts_Corp.getCellData(1, "MEMO_CONTN")));
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        await scwin.newpreCreateFrame(cmb_RegistTyp.BindColVal, "");
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.img_Regist_onclick" });
    }
};

/**
 * @method
 * @name grd_List_OnDblClick
 * @description grd_List 더블클릭 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} row 행 인덱스
 * @param {*} colid colid
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_List_OnDblClick = async function(row, colid) {
    try {
        scwin.fn_GetPar = scwin.getParUpdate; // 수정시 인수를 넘기는 function을 fn_GetPar란 변수에 할당, (팝업화면에서 참조하는 변수명이 fn_GetPar임)
        scwin.fn_SetPar = undefined;

        // 거래정지지정및해제구분코드 값 넘겨야함
        await scwin.newpreCreateFrame(dts_List.getCellData(dts_List.getRowPosition(), "HALT_DESNRELS_TP_CD"), dts_List.getCellData(dts_List.getRowPosition(), "TRD_HALT_STRT_DD"));
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.grd_List_OnDblClick" });
    }
};

/**
 * @method
 * @name rdo_DIRECT_DISCLS_onselchange
 * @description rdo_DIRECT_DISCLS onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.rdo_DIRECT_DISCLS_onselchange = function() {
    try {
        scwin.saveDirectDlsclsOnoff();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF05206.rdo_DIRECT_DISCLS_onselchange" });
    }
};

/**
 * @method
 * @name trs_process_OnSuccess
 * @description process On Success 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.trs_process_OnSuccess = async function() {
    try {
        const options = {
            id: "ULDSTF05017",
            title: "알림",
            type: "browserPopup",
            width: "400px",
            height: "300px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../lstproc/ULDSTF05017.gfm", options);

        const options2 = {
            id: "ULDSTF05018",
            title: "알림",
            type: "browserPopup",
            width: "400px",
            height: "250px",
            callbackFn: "scwin.popupCallback"
        };

        $c.win.openPopup("../lstproc/ULDSTF05018.gfm", options2);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05206.trs_process_OnSuccess" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description 채권상장법인 구분
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/tradingSuspension.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name bndListCorpYn
 * @description bnd List Corp Yn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.bndListCorpYn = async function() {
    url += "&service=krx.lds.stf.listingcommon.services.ListingCommonApp";
    url += "&outputMessageId=BNS_ISUR_INFO_INST";
    url += "&queryId=lds.stf.lstproc.select.isBndListStat";
    url += "&SCREN_ID=" + "ULDSTF05206.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&{P}ISUR_CD=" + txb_IsurCd.getValue();
    const sbmOptions = {
        id : "sbm_dts_Corp",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Corp=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

    return dts_Corp.getCellData(1, "BND_LIST_CORP_YN");
};

/**
 * @method
 * @name directDlsclsOnoff
 * @description direct Dlscls Onoff 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.directDlsclsOnoff = async function() {
    const sbmOptions = {
        id : "sbm_dts_Svcstat",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_Svcstat=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

/**
 * @method
 * @name popupCallback
 * @description browserPopup 팝업의 callback 함수. 부모창에서 팝업 결과 값을 처리한다.
 * @param {*} arg 팝업에서 전달받은 값
 * @returns {void}
 * @hidden N
 */
scwin.popupCallback = function (arg) {
    // TO-DO : arg 값 확인 후 업무 로직 추가
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name getParIsur
 * @description dialog 호출용 함수 예비심사청구제출기관 호출관련
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParIsur = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 코드값을 포함할 컨트롤
    arrPar[1] = txb_IsurNm.getValue(); // 명칭값을 포함할 컨트롤
    arrPar[2] = scwin.fr_SecuGrpId; // 명칭값을 포함할 컨트롤

    return arrPar.length;
};

/**
 * @method
 * @name setParIsur
 * @description set Par Isur 처리
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.setParIsur = async function(arrPar) {
    txb_IsurCd.setValue(arrPar[0].ISUR_CD);
    txb_IsurNm.setValue(arrPar[0].COM_NM);
    await scwin.search();
};

/**
 * @method
 * @name getParUpdate
 * @description 넘길 인수를 지정하는 펑션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParUpdate = function(arrPar) {
    // 넘길 인수를 지정하는 펑션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = dts_List.getCellData(dts_List.getRowPosition(), "bz_procs_no"); // 업무처리번호
    arrPar[5] = dts_List.getCellData(dts_List.getRowPosition(), "HALT_DESNRELS_TP_CD"); // 거래정지지정및해제구분코드
    arrPar[6] = scwin.spanYN; // 기업인수목적회사 구분_2010.05.30
    arrPar[7] = dts_List.getCellData(dts_List.getRowPosition(), "BND_LIST_CORP_YN"); // 채권상장법인 구분
    return arrPar.length;
};

/**
 * @method
 * @name getParNew
 * @description 신규생성시 지정하는 평션
 * @param {Array} arrPar 팝업 파라미터 배열(참조 채움)
 * @returns {void}
 * @hidden N
 */
scwin.getParNew = function(arrPar) {
    // 신규생성시 지정하는 평션
    arrPar[0] = txb_IsurCd.getValue(); // 발행기관코드값
    arrPar[1] = txb_IsurNm.getValue(); // 발행기관명
    arrPar[2] = scwin.fr_SecuGrpId; // 증권그룹구분
    arrPar[3] = scwin.fr_MktId; // 시장구분
    arrPar[4] = ""; // 신규작성시 업무처리번호는 없다.
    /*if(cmb_RegistTyp.BindColVal == "2" || cmb_RegistTyp.BindColVal == "4" ||
       cmb_RegistTyp.BindColVal == "5" || cmb_RegistTyp.BindColVal == "6" || cmb_RegistTyp.BindColVal == "7")
    {
    	arrPar[5] = "2"; // 2 정지 및 해제
    } else {
    	arrPar[5] = cmb_RegistTyp.BindColVal; // 거래정지지정및해제구분코드
    }*/
    arrPar[5] = cmb_RegistTyp.BindColVal;
    arrPar[6] = scwin.spanYN; // 기업인수목적회사 구분_2010.05.30
    arrPar[7] = scwin.bndYN; // 채권상장법인 구분

};

/**
     * @method
     * @name newpreCreateFrame
     * @description newpre Create Frame 처리
     * @param {*} arg arg
     * @param {String} startDd startDd
     * @returns {Promise<void>}
     * @hidden N
     */
scwin.newpreCreateFrame = async function(arg, startDd) {
    if (arg === "1" && startDd !== "") arg = "3";

    // 기업인수목적 회사 추가로 인한 변경 2010.05.30
    if (scwin.spanYN === "N") {
        // 0:지정, 1:해제, 2:지정및해제(유), 3:지정->해제
        // 4:매매거래정지 및 정지해제(중요내용공시)       99808,
        // 5:매매거래정지 및 정지해제(풍문 등 조회공시) 99810
        // 6:매매거래정지 및 정지해제(불성실공시)          99807
        // 7:매매거래정지 및 정지해제(우회상장심사)      99834
        switch (arg) {
            case "0": // HALT_DESNRELS_TP_CD 0 정지
                const options = {
                    id: "ULDSTF05207",
                    title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정",
                    type: "browserPopup",
                    width: "660px",
                    height: 455 + 35,
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("../lstproc/ULDSTF05207.gfm", options);
                break;
            case "2": // HALT_DESNRELS_TP_CD 2 정지 및 해제
                // frame.CreateDialogFrame("DLG_TRDSUSP_ANT","../lstproc/ULDSTF05209.gfm", fn_getSecuGrpNm(fr_SecuGrpId) +  " 매매거래정지 지정 및 해제", 200, 200, 650 , 450+35, "window");

                if (scwin.fr_SecuGrpId === 'MF') {
                    // by nhkw 20181116
                    const options = {
                        id: "ULDSTF05209",
                        title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제",
                        type: "browserPopup",
                        width: "650px",
                        height: 450 + 35,
                        callbackFn: "scwin.popupCallback"
                    };

                    $c.win.openPopup("../lstproc/ULDSTF05209.gfm", options);
                } else {
                    const options = {
                        id: "ULDSTF05209",
                        title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 지정 및 해제(상장규정)",
                        type: "browserPopup",
                        width: "650px",
                        height: 450 + 35,
                        callbackFn: "scwin.popupCallback"
                    };

                    $c.win.openPopup("../lstproc/ULDSTF05209.gfm", options);
                }
                break;
            case "3":
                const options2 = {
                    id: "ULDSTF05925",
                    title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 해제",
                    type: "browserPopup",
                    width: "650px",
                    height: 555 + 35,
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("../lstproc/ULDSTF05925.gfm", options2);
                break;
            case "4":
                const options3 = {
                    id: "ULDSTF05228",
                    title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(불성실공시)",
                    type: "browserPopup",
                    width: "700px",
                    height: 500 + 35,
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("../lstproc/ULDSTF05228.gfm", options3);
                break;
            case "5":
                const options4 = {
                    id: "ULDSTF05229",
                    title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(중요내용공시)",
                    type: "browserPopup",
                    width: "700px",
                    height: 500 + 35,
                    callbackFn: "scwin.popupCallback"
                };

                $c.win.openPopup("../lstproc/ULDSTF05229.gfm", options4);
                break;
            case "6":
                const options5 = {
                    id: "ULDSTF05230",
                    title: $c.lc.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 매매거래정지 및 정지해제(풍문 등 조회공시)",
                    type: "browserPopup",
                    width: "700px",
                    height: 500 + 35,
                    callbackFn: "scwin.popupCallback"
                };

