/**
 * @method
 * @name directDlsclsStatus
 * @description direct Dlscls Status 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.directDlsclsStatus = async function() {
    if (scwin.accessRights()) await scwin.directDlsclsOnoff();
};

/**
 * @method
 * @name accessRights
 * @description access Rights 처리
 * @returns {void}
 * @hidden N
 */
scwin.accessRights = function() {
    if ((js_dep_cd === "2600" && js_jobtitl === "40") || // 유가공시부&부서장
        (js_dep_cd === "2610" && js_jobtitl === "09") || // 유가공시제도팀&팀장
        js_dep_cd === "ZSYS") {
        panel_accessRights.show("");
        return true;
    } else {
        panel_accessRights.hide();
        return false;
    }
};

/**
 * @method
 * @name saveDirectDlsclsOnoff
 * @description save Direct Dlscls Onoff 처리
 * @returns {void}
 * @hidden N
 */
scwin.saveDirectDlsclsOnoff = function() {
    let url = "/tradingSuspension.do?method=updateSvcStat";
    url += "&SCREN_ID=" + "ULDSTF05206.xml";
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
    trs_process.Action = $c.lc.fn_encodeNSession(url);
    trs_process.KeyName = "toinb_dataid4";
    trs_process.KeyValue = "JSP(I:pInput=dts_Svcstat)";
    trs_process.Post();
};
